test:
assert_eq!(is_numeric_str("123"), true);
assert_eq!(is_numeric_str("12a"), false);
assert_eq!(is_numeric_str(""), false);

assert_eq!(is_even(4), true);
assert_eq!(is_even(3), false);
assert_eq!(is_even(0), true);

assert_eq!(is_perfect_square(16), true);
assert_eq!(is_perfect_square(15), false);
assert_eq!(is_perfect_square(0), true);

assert_eq!(is_power_of_two(8), true);
assert_eq!(is_power_of_two(6), false);
assert_eq!(is_power_of_two(1), true);
assert_eq!(is_power_of_two(0), false);

assert_eq!(is_armstrong(153), true);
assert_eq!(is_armstrong(154), false);
assert_eq!(is_armstrong(9), true);

assert_eq!(second_largest(&[1,3,2]), Some(2));
assert_eq!(second_largest(&[5,5]), None);
assert_eq!(second_largest(&[7]), None);

assert_eq!(is_sorted_asc(&[1,2,2,3]), true);
assert_eq!(is_sorted_asc(&[1,3,2]), false);
assert_eq!(is_sorted_asc(&[]), true);

assert_eq!(rotate_right(&[1,2,3,4], 1), vec![4,1,2,3]);
assert_eq!(rotate_right(&[1,2,3], 3), vec![1,2,3]);
assert_eq!(rotate_right(&[], 2), Vec::<i32>::new());

assert_eq!(bubble_sort(&[3,1,2]), vec![1,2,3]);
assert_eq!(bubble_sort(&[]), Vec::<i32>::new());
assert_eq!(bubble_sort(&[5,4,3,2,1]), vec![1,2,3,4,5]);

assert_eq!(mode_int(&[1,2,2,3]), Some(2));
assert_eq!(mode_int(&[]), None);
assert_eq!(mode_int(&[3,1,3,1]), Some(1));

assert_eq!(all_even(&[2,4,6]), true);
assert_eq!(all_even(&[2,3]), false);
assert_eq!(all_even(&[]), true);

assert_eq!(is_vowel_char('a'), true);
assert_eq!(is_vowel_char('E'), true);
assert_eq!(is_vowel_char('z'), false);
